import { Graderia } from "../../../../packages/types/graderia";
import { generateAsientos as generarAsientosCompletos } from "../../../../packages/types/generateAsientos";

// El catálogo tiene cientos de graderías y los asientos solo se necesitan al
// abrir el plano de una de ellas. Generarlos al importar este archivo bloqueaba
// la interfaz y hacía que navegación/login parecieran no responder.
function generateAsientos(metrosLineales: number, precioBase: number) {
  let asientos: ReturnType<typeof generarAsientosCompletos> | undefined;
  const materializar = () =>
    (asientos ??= generarAsientosCompletos(metrosLineales, precioBase));

  return new Proxy([] as ReturnType<typeof generarAsientosCompletos>, {
    get(_target, propiedad) {
      const valor = Reflect.get(materializar(), propiedad, materializar());
      return typeof valor === "function" ? valor.bind(materializar()) : valor;
    },
    set(_target, propiedad, valor) {
      return Reflect.set(materializar(), propiedad, valor, materializar());
    },
  });
}

// Generado automaticamente a partir de infopredio.json
