// Los asientos se generan con tu funcion real generateAsientos(metrosLineales, precioBase):
//   9 filas fijas x floor(metrosLineales * 2) columnas
// capacidad = 9 * floor(metrosLineales * 2), para que coincida exacto con asientos.length
// estado: ACTIVO -> 'disponible', NO VENTA -> 'agotado'
// precioMin = precioMax = precio del predio

